// What the redesign runner needs before it picks next month's style.
const rows = $input.all().map(i => i.json).filter(r => r.pr_number);
const byNewest = (a, b) => String(b.closed_at).localeCompare(String(a.closed_at));

return [{
  json: {
    generated_at: new Date().toISOString(),
    reviewed_prs: rows.length,
    // Researchers must not propose these styles again.
    avoid_styles: rows.filter(r => r.avoid).sort(byNewest)
      .map(r => ({ style: r.style_name, reason: r.reason, pr: r.pr_number, evidence: r.review_text })),
    // The implementer must respect these, whatever the style.
    lessons: rows.filter(r => r.lesson).sort(byNewest)
      .map(r => ({ reason: r.reason, pr: r.pr_number, style: r.style_name, evidence: r.review_text })),
    // Every closed-without-merge PR with the model's reading, for audit.
    rejected: rows.filter(r => r.outcome === 'rejected').sort(byNewest)
      .map(r => ({ pr: r.pr_number, style: r.style_name, reason: r.reason, confidence: r.reason_confidence, too_similar: r.too_similar_prob, quality_problem: r.quality_problem_prob, avoid_prob: r.avoid_prob })),
    accepted: rows.filter(r => r.outcome === 'merged').sort(byNewest)
      .map(r => ({ style: r.style_name, pr: r.pr_number, reception: r.reception })),
    // Low-confidence calls, kept out of the lists above.
    needs_review: rows.filter(r => r.needs_review).sort(byNewest)
      .map(r => ({ pr: r.pr_number, style: r.style_name, best_guess: r.reason, confidence: r.reason_confidence })),
  },
}];
